/* v555 : la position de la bonne réponse suit un plan équilibré — jamais plus
   de 20 % en A sur une partie — au lieu d'un simple mélange uniforme (25 %).
   Les propositions elles-mêmes restent tirées au hasard ; seule leur place
   est pilotée. Sans STIQuizAlea, on garde exactement le comportement v519. */
function appliquerPlanReponsesHc(sessionCalc) {
  var alea = window.STIQuizAlea;
  if (!alea || typeof alea.planReponses !== "function" || typeof alea.placerReponse !== "function") return sessionCalc;
  var tailles = sessionCalc.map(function (q) { return q.options ? q.options.length : 0; });
  var plan = alea.planReponses(tailles, { maxA: 0.2 });
  for (var i = 0; i < sessionCalc.length; i++) {
    var options = sessionCalc[i].options || [];
    var idx = -1;
    for (var k = 0; k < options.length; k++) {
      if (options[k] && options[k].ok) { idx = k; break; }
    }
    if (idx < 0) continue;
    sessionCalc[i].options = alea.placerReponse(options, idx, plan[i]).options;
  }
  return sessionCalc;
}

quiz/javascript.html:
/* v555 : la bonne réponse ne doit jamais dépasser 20 % des positions A
   sur une partie (un mélange uniforme en donne 25 %). Les propositions
   restent tirées au hasard ; seule leur place est pilotée. */
appliquerPlanReponsesJs(tirage) {
  const alea = window.STIQuizAlea;
  if (!alea || typeof alea.planReponses !== "function" || typeof alea.placerReponse !== "function") {
    return tirage;
  }
  const tailles = tirage.map((q) => (q.options ? q.options.length : 0));
  const plan = alea.planReponses(tailles, { maxA: 0.2 });
  for (let i = 0; i < tirage.length; i++) {
    const place = alea.placerReponse(tirage[i].options, tirage[i].answer, plan[i]);
    tirage[i].options = place.options;
    tirage[i].answer = place.index;
  }
  return tirage;
}

